css:
.tn-root{position:absolute;left:50%;bottom:72px;transform:translateX(-50%);display:flex;align-items:center;gap:var(--tn-gap);font-family:var(--tn-font);}
.tn-card{position:relative;display:flex;align-items:center;gap:18px;min-width:320px;padding:16px 34px 16px 18px;background:linear-gradient(180deg,rgba(5,9,16,.92),rgba(7,5,16,.86));border:1px solid rgba(255,255,255,.08);border-radius:var(--tn-radius);box-shadow:0 14px 44px rgba(0,0,0,.55),inset 0 0 26px rgba(255,255,255,.03);}
.tn-card:after{content:'';position:absolute;left:14px;right:14px;bottom:0;height:3px;border-radius:2px;}
.tn-a{border-color:rgba(34,211,238,.35);box-shadow:0 0 26px rgba(34,211,238,.18),0 14px 44px rgba(0,0,0,.55);}
.tn-a:after{background:linear-gradient(90deg,var(--tn-cyan),transparent);box-shadow:0 0 14px rgba(34,211,238,.7);}
.tn-b{border-color:rgba(244,114,182,.35);box-shadow:0 0 26px rgba(244,114,182,.18),0 14px 44px rgba(0,0,0,.55);}
.tn-b:after{background:linear-gradient(90deg,transparent,var(--tn-magenta));box-shadow:0 0 14px rgba(244,114,182,.7);}
.tn-avatar{position:relative;width:var(--tn-avatar-size);height:var(--tn-avatar-size);flex:0 0 auto;border-radius:50%;overflow:hidden;background:#0a0e16;display:flex;align-items:center;justify-content:center;}
.tn-a .tn-avatar{box-shadow:0 0 0 2px var(--tn-cyan),0 0 20px rgba(34,211,238,.5);}
.tn-b .tn-avatar{box-shadow:0 0 0 2px var(--tn-magenta),0 0 20px rgba(244,114,182,.5);}
.tn-avatar img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:none;z-index:1;}
.tn-avatar img.is-ready{display:block;}
.tn-fallback{position:relative;z-index:0;font-size:30px;font-weight:900;color:rgba(255,255,255,.55);}
.tn-meta{display:flex;flex-direction:column;gap:5px;position:relative;z-index:2;}
.tn-role{font-size:var(--tn-role-size);font-weight:700;letter-spacing:4px;line-height:1;}
.tn-a .tn-role{color:var(--tn-cyan);text-shadow:0 0 12px rgba(34,211,238,.75);}
.tn-b .tn-role{color:var(--tn-magenta);text-shadow:0 0 12px rgba(244,114,182,.75);}
.tn-role:empty{display:none;}
.tn-name{font-size:var(--tn-name-size);font-weight:800;color:#fff;line-height:1.16;white-space:nowrap;}
.tn-a .tn-name{text-shadow:0 0 10px rgba(34,211,238,.55),0 0 26px rgba(34,211,238,.28);}
.tn-b .tn-name{text-shadow:0 0 10px rgba(244,114,182,.55),0 0 26px rgba(244,114,182,.28);}
.tn-sep{position:relative;width:2px;height:76px;background:linear-gradient(180deg,transparent,var(--tn-cyan),var(--tn-accent),var(--tn-magenta),transparent);box-shadow:0 0 16px var(--tn-accent);display:flex;align-items:center;justify-content:center;}
.tn-dot{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:12px;height:12px;border-radius:50%;background:var(--tn-accent);box-shadow:0 0 16px var(--tn-accent);animation:tn-blink 2.2s ease-in-out infinite;}
@keyframes tn-blink{0%,100%{opacity:1;transform:translate(-50%,-50%) scale(1);}50%{opacity:.4;transform:translate(-50%,-50%) scale(.75);}}
